1	forgot_pass	forgot_password	Forgot password	<meta name="viewport" content="width=device-width, initial-scale=1.0"><meta http-equiv="Content-Type" content="text/html; charset<meta name="viewport" content="width=device-width, initial-scale=1.0"><meta http-equiv="Content-Type" content="text/html; charset=UTF-8">\r\n<style media="all" rel="stylesheet" type="text/css">/* Base ------------------------------ */\r\n    *:not(br):not(tr):not(html) {\r\n      font-family: Arial, 'Helvetica Neue', Helvetica, sans-serif;\r\n      -webkit-box-sizing: border-box;\r\n      box-sizing: border-box;\r\n    }\r\n    body {\r\n      \r\n    }\r\n    a {\r\n      color: #3869D4;\r\n    }\r\n\r\n\r\n    /* Masthead ----------------------- */\r\n    .email-masthead {\r\n      padding: 25px 0;\r\n      text-align: center;\r\n    }\r\n    .email-masthead_logo {\r\n      max-width: 400px;\r\n      border: 0;\r\n    }\r\n    .email-footer {\r\n      width: 570px;\r\n      margin: 0 auto;\r\n      padding: 0;\r\n      text-align: center;\r\n    }\r\n    .email-footer p {\r\n      color: #AEAEAE;\r\n    }\r\n  \r\n    .content-cell {\r\n      padding: 35px;\r\n    }\r\n    .align-right {\r\n      text-align: right;\r\n    }\r\n\r\n    /* Type ------------------------------ */\r\n    h1 {\r\n      margin-top: 0;\r\n      color: #2F3133;\r\n      font-size: 19px;\r\n      font-weight: bold;\r\n      text-align: left;\r\n    }\r\n    h2 {\r\n      margin-top: 0;\r\n      color: #2F3133;\r\n      font-size: 16px;\r\n      font-weight: bold;\r\n      text-align: left;\r\n    }\r\n    h3 {\r\n      margin-top: 0;\r\n      color: #2F3133;\r\n      font-size: 14px;\r\n      font-weight: bold;\r\n      text-align: left;\r\n    }\r\n    p {\r\n      margin-top: 0;\r\n      color: #74787E;\r\n      font-size: 16px;\r\n      line-height: 1.5em;\r\n      text-align: left;\r\n    }\r\n    p.sub {\r\n      font-size: 12px;\r\n    }\r\n    p.center {\r\n      text-align: center;\r\n    }\r\n\r\n    /* Buttons ------------------------------ */\r\n    .button {\r\n      display: inline-block;\r\n      width: 200px;\r\n      background-color: #3869D4;\r\n      border-radius: 3px;\r\n      color: #ffffff;\r\n      font-size: 15px;\r\n      line-height: 45px;\r\n      text-align: center;\r\n      text-decoration: none;\r\n      -webkit-text-size-adjust: none;\r\n      mso-hide: all;\r\n    }\r\n    .button--green {\r\n      background-color: #22BC66;\r\n    }\r\n    .button--red {\r\n      background-color: #dc4d2f;\r\n    }\r\n    .button--blue {\r\n      background-color: #3869D4;\r\n    }\r\n</style>\r\n<table cellpadding="0" cellspacing="0" class="email-wrapper" style="\r\n    width: 100%;\r\n    margin: 0;\r\n    padding: 0;" width="100%">\r\n\t<tbody>\r\n\t\t<tr>\r\n\t\t\t<td align="center">\r\n\t\t\t<table cellpadding="0" cellspacing="0" class="email-content" style="width: 100%;\r\n      margin: 0;\r\n      padding: 0;" width="100%"><!-- Logo -->\r\n\t\t\t\t<tbody><!-- Email Body -->\r\n\t\t\t\t\t<tr>\r\n\t\t\t\t\t\t<td class="email-body" style="width: 100%;\r\n    margin: 0;\r\n    padding: 0;\r\n    border-top: 1px solid #edeef2;\r\n    border-bottom: 1px solid #edeef2;\r\n    background-color: #edeef2;" width="100%">\r\n\t\t\t\t\t\t<table align="center" cellpadding="0" cellspacing="0" class="email-body_inner" style=" width: 570px;\r\n    margin:  14px auto;\r\n    background: #fff;\r\n    padding: 0;\r\n    border: 1px outset rgba(136, 131, 131, 0.26);\r\n    box-shadow: 0px 6px 38px rgb(0, 0, 0);\r\n       " width="570"><!-- Body content -->\r\n\t\t\t\t\t\t\t<thead style="background: #3869d4;">\r\n\t\t\t\t\t\t\t\t<tr>\r\n\t\t\t\t\t\t\t\t\t<th>\r\n\t\t\t\t\t\t\t\t\t<div align="center" style="padding: 15px; color: #000;"><a class="email-masthead_name" href="{var_action_url}" style="font-size: 16px;\r\n      font-weight: bold;\r\n      color: #bbbfc3;\r\n      text-decoration: none;\r\n      text-shadow: 0 1px 0 white;">{var_sender_name}</a></div>\r\n\t\t\t\t\t\t\t\t\t</th>\r\n\t\t\t\t\t\t\t\t</tr>\r\n\t\t\t\t\t\t\t</thead>\r\n\t\t\t\t\t\t\t<tbody>\r\n\t\t\t\t\t\t\t\t<tr>\r\n\t\t\t\t\t\t\t\t\t<td class="content-cell" style="padding: 35px;">\r\n\t\t\t\t\t\t\t\t\t<h1>Hi {var_user_name},</h1>\r\n\r\n\t\t\t\t\t\t\t\t\t<p>You recently requested to reset your password for your {var_website_name} account. Use this OTP to set a new password. This code expires in {var_otp_expire_minutes} minutes.</p>\r\n\t\t\t\t\t\t\t\t\t<!-- Action -->\n\t\t\t\t\t\t\t\t\t<p class="center" style="font-size:28px;letter-spacing:6px;font-weight:bold;color:#2F3133;text-align:center;">{var_otp}</p>\n\n\t\t\t\t\t\t\t\t\t<p>If you did not request a password reset, please ignore this email or reply to let us know.</p>\r\n\r\n\t\t\t\t\t\t\t\t\t<p>Thanks,<br />\r\n\t\t\t\t\t\t\t\t\t{var_sender_name}&nbsp;Team</p>\r\n\t\t\t\t\t\t\t\t\t\r\n\t\t\t\t\t\t\t\t\t</td>\r\n\t\t\t\t\t\t\t\t</tr>\r\n\t\t\t\t\t\t\t</tbody>\r\n\t\t\t\t\t\t</table>\r\n\t\t\t\t\t\t</td>\r\n\t\t\t\t\t</tr>\r\n\t\t\t\t</tbody>\r\n\t\t\t</table>\r\n\t\t\t</td>\r\n\t\t</tr>\r\n\t</tbody>\r\n</table>\r\n
