CREATE TABLE public.device_maintenance (
    id integer NOT NULL,
    device_id integer NOT NULL,
    maintenance_type character varying(50) NOT NULL,
    scheduled_date date,
    completed_date date,
    technician character varying(100),
    description text,
    cost numeric(10,2),
    status character varying(20) DEFAULT 'scheduled'::character varying,
    priority character varying(20) DEFAULT 'medium'::character varying,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    created_by integer,
    CONSTRAINT device_maintenance_maintenance_type_check CHECK (((maintenance_type)::text = ANY (ARRAY[('preventive'::character varying)::text, ('corrective'::character varying)::text, ('emergency'::character varying)::text, ('upgrade'::character varying)::text]))),
    CONSTRAINT device_maintenance_priority_check CHECK (((priority)::text = ANY (ARRAY[('low'::character varying)::text, ('medium'::character varying)::text, ('high'::character varying)::text, ('critical'::character varying)::text]))),
    CONSTRAINT device_maintenance_status_check CHECK (((status)::text = ANY (ARRAY[('scheduled'::character varying)::text, ('in_progress'::character varying)::text, ('completed'::character varying)::text, ('cancelled'::character varying)::text, ('overdue'::character varying)::text])))
);


