-- Name: devices device_config_inserted_trigger; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER device_config_inserted_trigger AFTER INSERT ON public.devices FOR EACH ROW EXECUTE FUNCTION public.notify_device_config_updated();


--
-- Name: devices device_config_updated_trigger; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER device_config_updated_trigger AFTER UPDATE ON public.devices FOR EACH ROW WHEN (((old.communication_config IS DISTINCT FROM new.communication_config) OR (old.metrics IS DISTINCT FROM new.metrics) OR (old.is_active IS DISTINCT FROM new.is_active) OR (old.is_deleted IS DISTINCT FROM new.is_deleted))) EXECUTE FUNCTION public.notify_device_config_updated();


